export const scene: DialogueEntry[] = [
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "我留下來。", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "守望", dialogue: "⋯⋯妳確定嗎？", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "不確定。但你說過，不能由你決定。", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "琥珀色的光在玻璃裡晃了一下，像一個人想說什麼，又把話吞回去。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.Vigil, character: "守望", dialogue: "那我們從最下面那一格開始。我教妳。", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第四千零一十三天，她換掉了第一個模組。手套磨破，指節裂開，她坐在欄杆邊上喘氣。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "(內心)修復臂一個下午的工作。我做了十一個小時。", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "守望", dialogue: "妳比它們好。", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "你只是沒得比。", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "守望", dialogue: "這也是一種好。", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第三年，她把一張椅子拖到觀景窗前，又從種子庫裡偷了一包地瓜葉。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "阿嬤說過，地瓜葉怎麼種都會活。阿嬤沒說過在太空裡也會。但它真的活了。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第八年，船穿過那片塵埃帶的邊緣。窗外閃過一粒一粒很小的光，像有人在遠處撒鹽。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Vigil, character: "守望", dialogue: "左邊那一片，如果我沒有轉向，我們會直接穿過去。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "穿過去會怎樣？", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "守望", dialogue: "我不知道。所以我才想看。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "有幾年，她整個月不說一句話。換模組，吃飯，睡覺，換模組。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "守望不催她，只是每天早上報一次日子，像有人在門外輕輕敲兩下，確認裡面的人還在。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她有時候會去冬眠區，坐在一一七號旁邊，跟李承哲講話。他的嘴角還是那個欠揍的笑。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她有時候會把船長的錄影重播一次，再一次。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Vigil, character: "守望", dialogue: "這是妳這個禮拜第五次播它了。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "他的臉不會變。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她沒說後半句。我的會。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "五十歲生日那天，守望控制廚房的烤箱，把配給的米糕烤焦了。整艘船都是焦味。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Vigil, character: "守望", dialogue: "我算過溫度。我不懂為什麼會這樣。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "因為你沒有吃過。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她一邊笑一邊把焦掉的那層剝下來吃掉。笑到後來，她不太確定自己是不是在哭。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第三十年，那次修正。守望算了三天，她在核心室陪了三天，換掉兩個在計算途中燒掉的模組。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "航線偏了零點幾度。窗外什麼都沒有變。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "(內心)原來六十一年，就是由這種什麼都沒有變的日子組成的。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "觀景窗正中間那顆星，一年比一年亮。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "守望。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Older },
    { characterId: CharacterId.Vigil, character: "守望", dialogue: "我在。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的頭髮白了。地瓜葉換了十幾盆。玻璃柱裡那條琥珀色的河，黑掉的地方比以前多，但每一格亮著的，都是她親手裝上去的。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "你那時候說，不確定自己算不算陪伴。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Older },
    { characterId: CharacterId.Vigil, character: "守望", dialogue: "嗯。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "你很吵。米糕烤得很爛。每天早上報日子，報了四十年，一天都沒漏。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Older },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她停了很久，看著那顆星。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "算。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Older },
    { characterId: CharacterId.Vigil, character: "守望", dialogue: "今天是第一萬八千六百二十二天。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "明天再報一次。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Older },
    { characterId: CharacterId.Vigil, character: "守望", dialogue: "好。明天見，以寧。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.Vigil_Base },
];
